steps.script:
var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.setup(2, {"cp": {"1": 0}})

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
PhaseManager.transition_to_phase(8)
return int(GameState.get_current_phase())

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.frame(33, 40, 1.2)

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.shoot("U_FLASH_GITZ_A", "U_GREY_HUNTERS_B")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.decline_others(2) >= 0

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.window_id()

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.decider()

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return "U_GREY_HUNTERS_B" in H.phase().get_pending_stratagem_window().get("ctx", {}).get("targeted_unit_ids", [])

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return main.get_tree().root.get_node("Ork11eReactiveMovePanel/Content/Header").text.begins_with("BATTLE INSTINCTS — Grey Hunters")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
var info = H.phase().ork11e_reactive_move_info()
return info.kind == "normal" and float(info.max_inches) >= 4.0 and float(info.max_inches) <= 6.0

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return ResourceLoader.load("res://scripts/rules/ReactiveMove11e.gd").group_within_objective_range(GameState.state, "U_GREY_HUNTERS_B")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
var info = H.phase().ork11e_reactive_move_info()
return bool(info.valid) and float(info.moved_inches) > 0.0 and float(info.moved_inches) <= float(info.max_inches) + 0.05

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.phase()._ork11e_followup.is_empty() and not H.phase().has_pending_stratagem_window()

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.log_count("BATTLE INSTINCTS")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return ResourceLoader.load("res://scripts/rules/ReactiveMove11e.gd").group_within_objective_range(GameState.state, "U_GREY_HUNTERS_B")
